class Order
  attr_reader :customer_id, :lines

  def initialize(customer_id)
    @customer_id = customer_id
    @lines = []
  end

  def add_line(line)
    raise OrderLimitExceeded, customer_id if total + line.price > LIMIT
    @lines << line
  end

  def total = @lines.sum(&:price)   # Ruby 3 endless method
end
